  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB____1LC0RB_0LC0LD_1RA1RA
      with (l := [SWin 1]).
    vm_compute; reflexivity.
  - (* C0 *)
