    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB____1LC0RB_0LC0LD_1RA1RA
      with (l := [SWin 1; SCycL 1 0; SWin 2; SCycR 1; SWin 1]).
    vm_compute; reflexivity.
  - (* D0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB____1LC0RB_0LC0LD_1RA1RA
      with (l := [SWin 1; SCycL 1 0; SWin 2; SCycR 1; SWin 2]).
    vm_compute; reflexivity.
Qed.

