  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB____1RC0LD_1LD1RA_0RC0LD
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 1; SWinL 3]).
