    apply (lap_of_run tm Cc true true cho_1RB____1RC1RC_1LD1RA_0RC0LD B0_1RB____1RC1RC_1LD1RA_0RC0LD B1_1RB____1RC1RC_1LD1RA_0RC0LD 6 8 p j' [] []).
