(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB____1RC1RD_1LD1RA_0RC0LD : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_000_100_1 q0 ++ [S0]) [] 0 Z0_1RB____1RC1RD_1LD1RA_0RC0LD /\
  cden (Ap_Alph_000_100_1 q0 ++ [S0]) [] 0 Z1_1RB____1RC1RD_1LD1RA_0RC0LD = Cc (Pos.succ p).
Proof.
