Lemma geo_1RB____1RC1RD_1LD1RA_0RC0LD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB____1RC1RD_1LD1RA_0RC0LD) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_000_100_1.cview_none_Alph_000_100_1 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB____1RC1RD_1LD1RA_0RC0LD
             = (StD, (rep [S0;S0;S0] (S j) ++ [S1], S0, [S1;S1;S1]))).
  { unfold cden, B1_1RB____1RC1RD_1LD1RA_0RC0LD, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
