  assert (HC : Cc (Pos.succ p) = (StD, ((rep [S0;S0;S0] (S j) ++ [S1]) ++ [S0], S0, [S1;S1;S1]))).
  { unfold Cc_1RB____1RC1RD_1LD1RA_0RC0LD. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB____1RC1RD_1LD1RA_0RC0LD. reflexivity.
