Qed.

(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB____1RC1RD_1LD1RA_0RC0LD : existsb (fun tg => cfires tmm_1RB____1RC1RD_1LD1RA_0RC0LD c0 13 tg) pins_1RB____1RC1RD_1LD1RA_0RC0LD = true.
