  - intros t Ht p _. apply fire_1RB____1RC1RD_1LD1RA_0RC0LD. exact Ht.
  - exact wit_1RB____1RC1RD_1LD1RA_0RC0LD.
  - apply qcleb_QC_32. reflexivity.
Qed.

